def lz4_decompress_block(comp, prefix=b""):
    hist = bytearray(prefix)
    prefix_len = len(prefix)
    ip = 0
    n = len(comp)
    while ip < n:
        token = comp[ip]
        ip += 1
        lit_len = token >> 4
        if lit_len == 15:
            while True:
                if ip >= n:
                    raise ValueError("lit len overflow")
                b = comp[ip]
                ip += 1
                lit_len += b
                if b != 255:
                    break
        if ip + lit_len > n:
            raise ValueError("lit overflow")
        hist.extend(comp[ip:ip+lit_len])
        ip += lit_len
        if ip >= n:
            break
        if ip + 2 > n:
            raise ValueError("offset overflow")
        offset = comp[ip] | (comp[ip+1] << 8)
        ip += 2
        if offset == 0:
            raise ValueError("offset zero")
        match_len = token & 0x0F
