# --- Frame compress ---
def compress_frame(data, block_code=None, content_size=False, block_checksum=False, frame_checksum=True, dict_bytes=b"", legacy=False):
    if legacy:
        out = bytearray()
        out.extend(struct.pack('<I', 0x184C2102))
        if len(data) == 0:
            return bytes(out)
        MAX_LEGACY = 8*1024*1024
        for off in range(0, len(data), MAX_LEGACY):
            chunk = data[off:off+MAX_LEGACY]
            if off == 0:
                pref = dict_bytes
            else:
                full = dict_bytes + data[:off]
                pref = full[-65535:] if len(full) > 65535 else full
            comp = lz4_compress_block(chunk, prefix=pref)
            out.extend(struct.pack('<I', len(comp)))
            out.extend(comp)
        return bytes(out)
    if block_code is None:
        bc = block_code_for_size(len(data))
    else:
        bc = block_code
    max_block = BLOCK_SIZES[bc]
    flg = 0x60
    if block_checksum:
        flg |= 0x10
    if content_size:
        flg |= 0x08
    if frame_checksum:
        flg |= 0x04
    bd = (bc << 4) & 0xF0
    hdr = bytearray()
    hdr.append(flg)
    hdr.append(bd)
    if content_size:
        hdr.extend(struct.pack('<Q', len(data)))
    hc = (xxh32(bytes(hdr), 0) >> 8) & 0xFF
    out = bytearray()
    out.extend(struct.pack('<I', 0x184D2204))
    out.extend(hdr)
    out.append(hc)
    for off in range(0, len(data), max_block):
        chunk = data[off:off+max_block]
        if off == 0:
            pref = dict_bytes
        else:
            full = dict_bytes + data[:off]
            if len(full) > 65535:
                pref = full[-65535:]
            else:
                pref = full
        comp = lz4_compress_block(chunk, prefix=pref)
        if len(comp) >= len(chunk) and len(chunk) > 0:
            out.extend(struct.pack('<I', len(chunk) | 0x80000000))
            out.extend(chunk)
            stored = chunk
        else:
            # for empty chunk? len 0 => comp is b"" (0 len), chunk len 0 => store as compressed? Actually empty data has no blocks? For empty data, loop range(0,0) => no blocks, just endmark. So this branch not taken for empty.
            # For non-empty where comp smaller, store compressed
            if len(chunk) == 0:
                # shouldn't happen
                continue
            out.extend(struct.pack('<I', len(comp)))
            out.extend(comp)
            stored = comp
        if block_checksum:
            out.extend(struct.pack('<I', xxh32(stored, 0)))
    out.extend(struct.pack('<I', 0))
    if frame_checksum:
        out.extend(struct.pack('<I', xxh32(data, 0)))
    return bytes(out)

class FrameError(Exception):
    def __init__(self, code, msg):
        super().__init__(msg)
        self.code = code
        self.msg = msg

def decompress_frame_all(data, dict_bytes=b""):
    out = bytearray()
    pos = 0
    n = len(data)
    if n == 0:
        return b""
    first = True
    while pos < n:
        if pos + 4 > n:
            if first and pos == 0:
                raise FrameError(40, "Error 40 : Unrecognized header : Magic Number unreadable \n")
            else:
                raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
        magic = struct.unpack('<I', data[pos:pos+4])[0]
        if magic == 0x184D2204:
            first = False
            if pos + 4 + 2 > n:
                raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
            flg = data[pos+4]
            bd = data[pos+5]
            version = (flg >> 6) & 0x03
            if version != 1:
                raise FrameError(34, "Error 34 : Decompression error : ERROR_reservedFlag_set \n")
            if flg & 0x02:
                raise FrameError(34, "Error 34 : Decompression error : ERROR_reservedFlag_set \n")
            if bd & 0x0F:
                raise FrameError(34, "Error 34 : Decompression error : ERROR_reservedFlag_set \n")
            block_code = (bd >> 4) & 0x07
            if block_code < 4 or block_code > 7:
                raise FrameError(34, "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n")
            max_block = BLOCK_SIZES[block_code]
            has_bx = bool(flg & 0x10)
            has_cs = bool(flg & 0x08)
            has_fc = bool(flg & 0x04)
            has_did = bool(flg & 0x01)
            hdr_len = 2
            if has_cs:
                if pos + 4 + hdr_len + 8 > n:
                    raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
                hdr_len += 8
            if has_did:
                if pos + 4 + hdr_len + 4 > n:
                    raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
                hdr_len += 4
            if pos + 4 + hdr_len + 1 > n:
                raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
            hc = data[pos+4+hdr_len]
            hdr_len += 1
            hdr_bytes = data[pos+4:pos+4+hdr_len-1]
            exp_hc = (xxh32(hdr_bytes, 0) >> 8) & 0xFF
            if hc != exp_hc:
                raise FrameError(34, "Error 34 : Decompression error : ERROR_headerChecksum_invalid \n")
            pos += 4 + hdr_len
            frame_start = len(out)
            while True:
                if pos + 4 > n:
                    raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
                raw = struct.unpack('<I', data[pos:pos+4])[0]
                pos += 4
                if raw == 0:
                    break
                is_comp = not (raw & 0x80000000)
                blen = raw & 0x7FFFFFFF
                if blen > max_block:
                    raise FrameError(34, "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n")
                if pos + blen > n:
                    raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
                blk = data[pos:pos+blen]
                pos += blen
                if has_bx:
                    if pos + 4 > n:
                        raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
                    scrc = struct.unpack('<I', data[pos:pos+4])[0]
                    pos += 4
                    if scrc != xxh32(blk, 0):
                        raise FrameError(34, "Error 34 : Decompression error : ERROR_blockChecksum_invalid \n")
                if not is_comp:
                    out.extend(blk)
                else:
                    frame_so_far = bytes(out[frame_start:])
                    if len(frame_so_far) == 0:
                        pref = dict_bytes
                        if len(pref) > 65535:
                            pref = pref[-65535:]
                    else:
                        comb = dict_bytes + frame_so_far if dict_bytes else frame_so_far
                        # comb may be large; only tail needed
                        if len(comb) > 65535:
                            # need dict tail + frame tail? Actually need last 64KB of combined (dict+frame). For large frame, frame tail alone suffices.
                            # To avoid copying large, take tail
                            if len(frame_so_far) >= 65535:
                                pref = frame_so_far[-65535:]
                            else:
                                # need part of dict + all frame
                                need = 65535 - len(frame_so_far)
                                dt = dict_bytes[-need:] if len(dict_bytes) > need else dict_bytes
                                pref = dt + frame_so_far
                        else:
                            pref = comb
                    try:
                        dec = lz4_decompress_block(blk, prefix=pref)
                    except Exception:
                        raise FrameError(34, "Error 34 : Decompression error : ERROR_decompressionFailed \n")
                    if len(dec) > max_block:
                        raise FrameError(34, "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n")
                    out.extend(dec)
            if has_fc:
                if pos + 4 > n:
                    raise FrameError(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n")
                sfc = struct.unpack('<I', data[pos:pos+4])[0]
                pos += 4
                fdata = bytes(out[frame_start:])
                if sfc != xxh32(fdata, 0):
                    raise FrameError(34, "Error 34 : Decompression error : ERROR_contentChecksum_invalid \n")
        elif magic == 0x184C2102:
            first = False
            pos += 4
            leg_start = len(out)
            if pos == n:
                pass
            else:
                while pos < n:
                    if pos + 4 > n:
                        raise FrameError(61, "Error 61 : Error: cannot read block size in Legacy format \n")
                    bsz = struct.unpack('<I', data[pos:pos+4])[0]
                    pos += 4
                    if bsz == 0:
                        break
