# --- helpers for messages ---
def eprint(s):
    sys.stderr.write(s)
    sys.stderr.flush()

def format_size(s):
    if s < 1024:
        return f"{float(s):.2f}"
    elif s < 1024*1024:
        return f"{float(s)/1024:.2f}K"
    else:
        return f"{float(s)/(1024*1024):.2f}M"

def format_ratio(comp, uncomp):
    if uncomp == 0 or uncomp is None:
        return "-"
    # ratio = comp/uncomp*100?
    # For list, ratio is comp/uncomp*100 with 2 decimals + %? Check: 42/1234=3.40% yes.
    # For verbose list, same.
    # For normal list, ratio column width? We'll just return f"{comp/uncomp*100:.2f}%"
    return f"{float(comp)/float(uncomp)*100:.2f}%"

# display helpers
# quiet: 0,1,2 ; verbose: bool
# For warnings category A (using blocks, compressed filename, decoding file, warning content-size, etc.): show if quiet==0 or (verbose and quiet==1)
def show_warningA(quiet, verbose):
    return quiet == 0 or (verbose and quiet == 1)
def show_error(quiet, verbose):
    # errors + category B warnings (won't be used, dir errors, etc.): show if quiet<2 or (verbose and quiet==2)
    return quiet < 2 or (verbose and quiet == 2)
def show_progress_file(quiet, verbose, base_is_file):
    # base_is_file: True if output is file (not stdout), False if stdout
    # displayLevel = base + verbose - quiet ; base 1 for file, 0 for stdout
    base = 1 if base_is_file else 0
    lvl = base + (1 if verbose else 0) - quiet
    return lvl >= 1
def show_verbose_header(quiet, verbose):
    return verbose and quiet == 0

